  n=len(x)//chunks
  for j in range(chunks):up(c,x[j*n:] if j==chunks-1 else x[j*n:(j+1)*n],len(x)-j*n if j==chunks-1 else n)
  fin(o,c); print(chunks,time.perf_counter()-t)
